from collections import deque
left={(1,0),(2,0),(3,0),(4,0)}|{(x,y) for y in (1,2) for x in range(5)}|{(0,3),(1,3)}|{(0,y) for y in (4,5)}|{(0,6),(1,6)}|{(0,7),(1,7),(2,7)}|{(x,8) for x in range(5)}
