shared={(x,9) for x in range(1,7)}
L=left|shared; R=right|shared
start=((1,1),(6,0)); actions={1:(0,-1),2:(0,1),3:(-1,0),4:(1,0)}
def move(p,d,S):
 q=(p[0]+d[0],p[1]+d[1]);return q if q in S else p
q=deque([start]);prev={start:None};how={}
while q:
 s=q.popleft()
 if s[0]==s[1]:
  path=[]
  while prev[s] is not None:path.append(how[s]);s=prev[s]
  print(len(path),path[::-1]);break
 for a,d in actions.items():
  ns=(move(s[0],d,L),move(s[1],d,R))
  if ns not in prev:prev[ns]=s;how[ns]=a;q.append(ns)
